    #[test]
    fn overview_uses_canonical_boundary_precision_currency_and_party_identity() {
        let start = Some("2024-07-09T00:00:00Z");
        let overview = summarize_overview(vec![
            member(1, 1, vec![
                (Some("2024-07-08T23:59:59.999999Z"), Some("100"), Some("GBP")),
                (None, Some("200"), Some("GBP")),
                (start, Some("9007199254740993.123456789"), Some("GBP")),
                (start, None, Some("EUR")),
                (start, None, Some("GBP")),
            ]),
            member(2, 2, vec![(start, Some("-9007199254740993.023456789"), Some("GBP"))]),
            member(3, 1, vec![(start, Some("0"), Some("GBP"))]),
            member(4, 1, vec![(start, Some("8"), None)]),
            member(5, 1, vec![(start, None, Some("USD"))]),
            member(6, 1, vec![]),
        ]);
        assert_eq!(overview.member_count, 6);
        assert_eq!(overview.unavailable_member_count, 3);
        assert!(overview.incomplete);
        assert_eq!(overview.parties.len(), 2);
        assert_eq!(overview.parties[0].member_count, 5);
        assert_eq!(overview.parties[0].total.declaration_count, 6);
        assert_eq!(overview.parties[0].total.amount, Some("9007199254740993.123456789".parse().unwrap()));
        assert!(overview.parties[0].total.incomplete);
        assert_eq!(overview.parties[1].total.amount, Some("-9007199254740993.023456789".parse().unwrap()));
        assert!(!overview.parties[1].total.incomplete);
        assert_eq!(overview.top_members.iter().map(|value| value.member.id.value()).collect::<Vec<_>>(), vec![1, 3, 2]);
        assert_eq!(overview.top_members[0].total.declaration_count, 3);
        assert!(overview.top_members[0].total.incomplete);
        assert_eq!(overview.quartiles.iter().map(|value| value.member_count).collect::<Vec<_>>(), vec![0, 1, 1, 1]);
        assert_eq!(overview.quartiles[0].minimum, None);
        assert_eq!(overview.quartiles[1].minimum, overview.parties[1].total.amount);
    }

    #[test]
    fn overview_rank_groups_and_top_five_have_deterministic_ties() {
        let overview = summarize_overview((1..=10).rev().map(|id| member(id, 1, vec![(Some("2024-07-09T00:00:00Z"), Some("1.000000000000000001"), Some("GBP"))])).collect());
        assert_eq!(overview.top_members.iter().map(|value| value.member.id.value()).collect::<Vec<_>>(), vec![1, 2, 3, 4, 5]);
        assert_eq!(overview.quartiles.iter().map(|value| value.member_count).collect::<Vec<_>>(), vec![2, 3, 2, 3]);
        assert!(overview.quartiles.iter().all(|value| value.minimum == value.maximum && value.incomplete_member_count == 0));
        assert_eq!(overview.parties[0].total.amount, Some("10.000000000000000010".parse().unwrap()));
        let empty = summarize_overview(Vec::new());
        assert_eq!(empty.member_count, 0);
        assert!(empty.top_members.is_empty());
        assert!(empty.parties.is_empty());
        assert!(empty.quartiles.iter().all(|value| value.member_count == 0 && value.minimum.is_none() && value.maximum.is_none()));
    }
}
